function showFailureSmoke(){const pot=document.querySelector('.cauldron');if(!pot)return;pot.querySelectorAll('.enhancement-failure-fx').forEach(node=>node.remove());const effect=document.createElement('div');effect.className='enhancement-failure-fx'+(gameSettings.reducedMotion?' still-smoke':'');effect.setAttribute('aria-hidden','true');const burst=document.createElement('i');burst.className='enhancement-burst';effect.append(burst);for(let i=0;i<9;i++){const smoke=document.createElement('i');smoke.className='enhancement-smoke';smoke.style.setProperty('--drift',(i-4)*29+'px');smoke.style.setProperty('--delay',i*30+'ms');effect.append(smoke);}pot.append(effect);showCauldronTexture('failed',800,effect);setTimeout(()=>effect.remove(),2300);}
