function addMenuReturn(dialog){if(dialog.id!=='game-menu'&&!dialog.querySelector('[data-back-to-menu]')){const button=document.createElement('button');button.type='button';button.className='back-to-menu';button.dataset.backToMenu='';button.textContent='← Back to menu';button.onclick=()=>{if(dialog.id==='catalog-dialog'&&catalogView!==null){catalogView=null;renderCatalog();return;}document.querySelectorAll('dialog[open]').forEach(open=>open.close());$('game-menu-open').click();};const close=dialog.querySelector('.close');if(close)close.after(button);else dialog.prepend(button);}pinDialogHeader(dialog);}

document.querySelectorAll('dialog').forEach(addMenuReturn);
new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes){if(node.nodeType===1&&node.matches('dialog'))addMenuReturn(node);}}).observe(document.body,{childList:true});

const helperCatElements=new Map();
function syncHelperCats(){const helpers=game.state.helpers,ingredients=$('ingredients'),left=ingredients.offsetLeft||0,width=ingredients.clientWidth;for(const[h,node]of helperCatElements)if(!helpers.includes(h)){node.remove();helperCatElements.delete(h);}helpers.forEach((h,index)=>{let node=helperCatElements.get(h);if(!node){node=document.createElement('div');node.className='conveyor-cat';const face=document.createElement('img'),hand=document.createElement('img'),timer=document.createElement('small');face.className='helper-face';face.src=art(h.kind==='blackcat'?'BlackcatDialogue.png':'PushcatDialogue.png');face.alt=h.kind==='blackcat'?'Blackcat helper':'Pushcat helper';hand.className='helper-hand';hand.src=art(h.kind==='blackcat'?'BlackcatHand.png':'PushcatHand.png');hand.alt='';hand.setAttribute('aria-hidden','true');node.append(face,hand,timer);ingredients.parentElement.append(node);helperCatElements.set(h,node);}const position=(left+width*(h.slot+.5)/ECONOMY.helpers.maxActive)+'px';if(node.style.left!==position)node.style.left=position;setText(node.querySelector('small'),Math.ceil(h.remainingMs/1000)+'s');});}
function animateIngredient(family,tier,id=null,helper=null,kind=null){if(!kind){if(helper)playOriginalSfx('Pushcat Hit.wav',.12,120);else playIngredientPlop(reducedMotion?0:INGREDIENT_FLIGHT_MS);}if(reducedMotion){if(!kind)showCauldronTexture('plop',180);return;}const source=id!==null?beltElements.get(id):$('ingredients').children[family],target=document.querySelector(kind==='ticket'?'#tickets-display':kind==='solution'?'.solution-balance':'.liquid');if(!source||!target)return;const from=source.getBoundingClientRect(),to=target.getBoundingClientRect(),image=document.createElement('img'),x=from.left+from.width/2-20,y=from.top+from.height/2-20,dx=to.left+to.width/2-20-x,dy=to.top+to.height/2-20-y;image.src=art(kind==='ticket'?'Nyan-Ticket.png':kind==='solution'?'OriginalMiracleSolution.png':FAMILIES[family].materials[tier].image);image.alt='';image.className='falling-ingredient';image.style.left=x+'px';image.style.top=y+'px';document.body.append(image);const flight=image.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx*.35}px,${Math.min(-24,dy*.15)}px) rotate(-15deg) scale(.95)`,opacity:1,offset:.3},{transform:`translate(${dx}px,${dy}px) rotate(25deg) scale(.35)`,opacity:0}],{duration:INGREDIENT_FLIGHT_MS,easing:'ease-in',fill:'forwards'});flight.finished.then(()=>{if(!kind)showCauldronTexture('plop',350);}).catch(()=>{}).finally(()=>image.remove());const hand=helperCatElements.get(helper)?.querySelector('.helper-hand');if(hand){hand.getAnimations().forEach(a=>a.cancel());hand.animate([{transform:'translate(-50%,0)',opacity:0},{transform:'translate(-50%,24px)',opacity:1,offset:.28},{transform:'translate(-50%,28px)',opacity:1,offset:.58},{transform:'translate(-50%,0)',opacity:0}],{duration:Math.max(140,Math.min(320,helper.intervalMs*.85)),easing:'ease-in-out'});}}
function renderHelper(){const helpers=game.state.helpers,button=$('pushcat-summon');button.disabled=helpers.length>=ECONOMY.helpers.maxActive||game.state.tickets<ECONOMY.helpers.ticketCost;setText($('pushcat-label'),'Summon Pushcat');setText($('pushcat-status'),helpers.length?helpers.length+' / '+ECONOMY.helpers.maxActive+' cats · '+(!game.state.potion?'Paused':'Working'):'1 ticket');syncHelperCats();}

$('pushcat-summon').onclick=()=>{const tickets=game.state.tickets,rubies=game.state.rubies,stats={...game.state.helperStats},helpers=[...game.state.helpers],kind=game.summonHelper();if(!kind)return;save(true);if(!saveOK||saveBlocked){game.state.tickets=tickets;game.state.rubies=rubies;game.state.helperStats=stats;game.state.helpers=helpers;saveDirty=true;notice('Could not save the summon. Your ticket was returned.');}else{playOriginalSfx('Summon Pushcat.wav',.2);notice((kind==='blackcat'?'Blackcat':'Pushcat')+' is here to help! Pick the first ingredient to begin.','success');}render();};window.refreshHelper=renderHelper;renderHelper();

function decorateGameText(root){if(!root)return;const nodes=[];if(root.nodeType===3)nodes.push(root);else if(root.nodeType===1){if(root.closest('script,style,textarea,input,select,option,pre,code,[contenteditable],.reward-chip,.ui-family'))return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode())nodes.push(walker.currentNode);}for(const node of nodes){const parent=node.parentElement;if(!parent||parent.closest('script,style,textarea,input,select,option,pre,code,[contenteditable],.reward-chip,.ui-family'))continue;const text=node.nodeValue,pattern=/\b(Life|Mana|Stamina)\b|\b(\d+(?:,\d{3})*(?:\.\d+)?)\s+(failure protection(?: charges?)?|protection(?: charges?)?|enhancement(?: bonus(?:es)?)?(?: charges?)?|double-sale(?: charges?)?|selling(?: bonus(?:es)?)?(?: charges?)?|sale boost(?: charges?)?|Pushcat tickets?|tickets?|rubies|ruby|likeability|expedition stamps?|stamps?)\b/g;let match,last=0,fragment=null;while((match=pattern.exec(text))){fragment??=document.createDocumentFragment();fragment.append(document.createTextNode(text.slice(last,match.index)));if(match[1]){const span=document.createElement('span');span.className='ui-family';span.textContent=match[1];span.style.color=FAMILIES.find(f=>f.label===match[1]).color;fragment.append(span);}else{const label=match[3],kind=/protection/.test(label)?'protection':/enhancement/.test(label)?'enhancement':/double-sale|selling|sale boost/.test(label)?'selling':/ticket/.test(label)?'tickets':/rub/.test(label)?'rubies':/likeability/.test(label)?'likeability':'stamps';fragment.append(rewardChip(kind,match[2]));}last=pattern.lastIndex;}if(fragment){fragment.append(document.createTextNode(text.slice(last)));node.replaceWith(fragment);}}}
decorateGameText(document.body);const presentationObserver=new MutationObserver(changes=>{const roots=new Set();for(const change of changes){if(change.type==='characterData')roots.add(change.target);else for(const node of change.addedNodes)roots.add(node);}for(const root of roots)if(root.isConnected)decorateGameText(root);});presentationObserver.observe(document.body,{childList:true,subtree:true,characterData:true});
